import {definitions as defs,seed,today,nextDate,escapeHTML as esc,validate,validateBackup} from './domain.js';
const $=s=>document.querySelector(s),key='warebase-v1';let data,view='dashboard',query='',filter='',editing=null;
try{const saved=localStorage.getItem(key);data=saved?validateBackup(JSON.parse(saved)):seed();if(!saved)localStorage.setItem(key,JSON.stringify(data));}catch(e){data=seed();setTimeout(()=>toast('無法讀取已存資料，使用暫存示範資料；請檢查瀏覽器儲存空間。'),500);}
const icons={dashboard:'◫',assets:'▤',orders:'☷',plans:'▦',inspections:'☑',parts:'▧',audit:'◷'};
const names={dashboard:'總覽儀表板',...Object.fromEntries(Object.entries(defs).map(([k,v])=>[k,v.title]))};
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),4500);}
function save(next,message){next.audit.unshift({name:message,time:new Date().toISOString()});next.audit=next.audit.slice(0,1000);try{localStorage.setItem(key,JSON.stringify(next));data=next;return true;}catch{toast('儲存失敗，請先備份並釋放瀏覽器空間。');return false;}}
const badge=s=>`<span class="badge ${['正常','合格','已完成'].includes(s)?'green':['緊急','異常','待維修','逾期'].includes(s)?'red':['進行中','高','待處理','待巡檢'].includes(s)?'amber':'gray'}">${esc(s)}</span>`;
const assetName=id=>data.assets.find(a=>a.id===id)?.name||id;
const overdue=r=>r.due<today()&&r.status!=='已完成';
const money=n=>new Intl.NumberFormat('zh-TW').format(n);
function titleBlock(title,desc,actions=''){return `<div class="page-heading"><div><div class="eyebrow">WAREHOUSE OPERATIONS / ${String(Object.keys(names).indexOf(view)+1).padStart(2,'0')}</div><h1>${title}</h1><p>${desc}</p></div><div class="actions">${actions}</div></div>`;}
function table(headers,rows){return `<div class="table-scroll"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.join(''):`<tr><td colspan="${headers.length}" class="empty">沒有符合條件的紀錄</td></tr>`}</tbody></table></div>`;}
function dashboard(){const open=data.orders.filter(o=>o.status!=='已完成'),risk=data.assets.filter(a=>a.status!=='正常'),due=data.plans.filter(p=>p.due<=nextDate(today(),7)),low=data.parts.filter(p=>Number(p.quantity)<Number(p.minimum));const recent=[...open].sort((a,b)=>a.due.localeCompare(b.due));return titleBlock('掌握設施，讓營運順暢。','設備狀態、維修進度與保養重點，一次掌握。',`<span class="date">${new Date().toLocaleDateString('zh-TW',{year:'numeric',month:'long',day:'numeric',weekday:'long'})}</span><button class="primary" data-new="orders">＋ 建立工單</button>`)+`<div class="notice"><span>◉</span><div><b>歡迎使用 WAREBASE</b>　目前為含示範資料的本機工作空間，可直接編輯並匯出備份。</div><a href="#assets">查看設備 →</a></div><section class="stats"><article><span>設備總數 <i>▤</i></span><strong>${data.assets.length}<small>台</small></strong><p><em>${data.assets.filter(a=>a.status==='正常').length} 台正常運作</em> · ${risk.length} 台需關注</p></article><article><span>待處理工單 <i>☷</i></span><strong>${open.length}<small>筆</small></strong><p><b class="red-text">${open.filter(overdue).length} 筆已逾期</b> · 需優先安排</p></article><article><span>近期保養 <i>▦</i></span><strong>${due.length}<small>項</small></strong><p>未來 7 天內到期的保養計畫</p></article><article><span>巡檢合格率 <i>☑</i></span><strong>${data.inspections.some(i=>i.status!=='待巡檢')?Math.round(100*data.inspections.filter(i=>i.status==='合格').length/data.inspections.filter(i=>i.status!=='待巡檢').length):0}<small>%</small></strong><p>${data.inspections.filter(i=>i.status==='異常').length} 項異常 · 已完成巡檢為分母</p></article></section><section class="dashboard-grid"><article class="panel wide"><div class="panel-head"><div><h2>維修工作佇列 <span class="count">${open.length}</span></h2><p>依到期日排序，優先處理現場問題</p></div><a href="#orders">全部工單 ↗</a></div>${table(['工單 / 設備','優先級','負責人','到期日','狀態'],recent.slice(0,5).map(o=>`<tr data-edit="orders" data-id="${esc(o.id)}" tabindex="0" role="button" aria-label="編輯 ${esc(o.name)}"><td><b>${esc(o.name)}</b><small>${esc(o.id)} · ${esc(assetName(o.asset))}</small></td><td>${badge(o.priority)}</td><td><span class="person">${esc(o.owner[0])}</span>${esc(o.owner)}</td><td class="${overdue(o)?'red-text':''}">${esc(o.due)}${overdue(o)?'<small>已逾期</small>':''}</td><td>${badge(o.status)}</td></tr>`))}</article><article class="panel"><div class="panel-head"><div><h2>設備健康分布</h2><p>目前設備運作狀態</p></div><span>◉</span></div><div class="health"><div class="donut" style="--percent:${data.assets.length?100*data.assets.filter(a=>a.status==='正常').length/data.assets.length:0}%;--repair:${data.assets.length?100*data.assets.filter(a=>a.status!=='停用').length/data.assets.length:0}%"><div><strong>${data.assets.length?Math.round(100*data.assets.filter(a=>a.status==='正常').length/data.assets.length):0}%</strong><small>正常運作</small></div></div><div class="legend">${['正常','待維修','停用'].map((s,i)=>`<p><span><i class="dot d${i}"></i>${s}</span><b>${data.assets.filter(a=>a.status===s).length}</b></p>`).join('')}</div></div><a class="panel-link" href="#assets">前往設備台帳 <span>→</span></a></article><article class="panel wide"><div class="panel-head"><div><h2>保養計畫</h2><p>預防性維護，減少非預期停機</p></div><a href="#plans">管理排程 ↗</a></div><div class="plan-list">${[...data.plans].sort((a,b)=>a.due.localeCompare(b.due)).slice(0,3).map(p=>`<div class="plan-row"><div class="calendar"><b>${p.due.slice(8)}</b><small>${p.due.slice(5,7)} 月</small></div><div><b>${esc(p.name)}</b><small>${esc(assetName(p.asset))} · 每 ${esc(p.interval)} 天</small></div><span class="muted">${esc(p.owner)}</span><button data-complete="${esc(p.id)}">完成保養 ↗</button></div>`).join('')||'<p class="empty">尚無保養計畫</p>'}</div></article><article class="panel attention"><div class="panel-head"><div><h2>需要關注</h2><p>追蹤潛在的營運風險</p></div><span>↗</span></div><a href="#orders"><span class="alert-symbol">!</span><div><b>${open.filter(overdue).length} 筆逾期工單</b><small>安排人員與處理時間</small></div><span>→</span></a><a href="#parts"><span class="alert-symbol amber">▧</span><div><b>${low.length} 項備品低於安全庫存</b><small>及時補貨，維持維修量能</small></div><span>→</span></a><a href="#inspections"><span class="alert-symbol">☑</span><div><b>${data.inspections.filter(i=>i.status==='異常').length} 項巡檢異常</b><small>查看異常並建立維修工單</small></div><span>→</span></a></article></section>`;}
function listPage(){const def=defs[view];if(view==='audit')return titleBlock('操作紀錄','保留最近 1,000 筆本機操作紀錄。')+`<section class="panel">${table(['時間','操作內容'],data.audit.map(a=>`<tr><td>${esc(new Date(a.time).toLocaleString('zh-TW'))}</td><td>${esc(a.name)}</td></tr>`))}</section>`;const rows=data[view].filter(r=>(!query||Object.values(r).join(' ').toLowerCase().includes(query.toLowerCase())||assetName(r.asset).includes(query))&&(!filter||(filter==='低庫存'?Number(r.quantity)<Number(r.minimum):r.status===filter||r.zone===filter)));const fieldEntries=Object.entries(def.fields).filter(([k])=>k!=='note');let options=view==='assets'?['正常','待維修','停用']:view==='orders'?['待處理','進行中','已完成']:view==='inspections'?['待巡檢','合格','異常']:view==='parts'?['低庫存']:[];return titleBlock(def.title,{assets:'建立設備履歷，追蹤位置、負責人與健康狀態。',orders:'從報修、指派到完工，記錄每一項維修工作。',plans:'以週期管理保養，完成後自動推算下次日期。',inspections:'記錄巡檢結果，將異常轉為可追蹤的工單。',parts:'管理維修備品與安全庫存，避免缺料中斷作業。'}[view],`<button id="csv">↓ 匯出 CSV</button><button class="primary" data-new="${view}">＋ 新增${def.singular}</button>`)+`<section class="panel"><div class="toolbar"><label class="search">⌕ <input id="search" aria-label="搜尋紀錄" placeholder="搜尋名稱、編號、設備或人員…" value="${esc(query)}"></label><select id="filter" aria-label="篩選狀態"><option value="">全部紀錄</option>${options.map(s=>`<option ${filter===s?'selected':''}>${s}</option>`).join('')}</select><span>${rows.length} 筆紀錄</span></div>${table(['編號',...fieldEntries.map(([,v])=>v[0]),'操作'],rows.map(r=>`<tr><td class="code">${esc(r.id)}</td>${fieldEntries.map(([k])=>`<td>${['status','priority'].includes(k)?badge(r[k]):k==='asset'?esc(assetName(r[k])):k==='cost'?'NT$ '+money(Number(r[k])):esc(r[k])}${k==='quantity'&&Number(r.quantity)<Number(r.minimum)?'<small class="red-text">低於安全庫存</small>':''}</td>`).join('')}<td class="row-actions"><button data-edit="${view}" data-id="${esc(r.id)}">編輯</button>${view==='plans'?`<button data-complete="${esc(r.id)}">完成</button>`:view==='inspections'&&r.status==='異常'?`<button data-convert="${esc(r.id)}">轉工單</button>`:''}</td></tr>`))}</section>`;}
function render(){view=location.hash.slice(1)||'dashboard';if(!names[view])view='dashboard';$('#breadcrumb').textContent=names[view];$('#nav').innerHTML=Object.entries(names).map(([k,v])=>`<a href="#${k}" class="${view===k?'active':''}"><span>${icons[k]}</span>${v}${k==='orders'?`<em>${data.orders.filter(o=>o.status!=='已完成').length}</em>`:''}</a>`).join('');$('#main').innerHTML=view==='dashboard'?dashboard():listPage();}
function openEditor(type,id){editing={type,id};const def=defs[type],row=data[type].find(r=>r.id===id)||{};$('#dialog-title').textContent=(id?'編輯':'新增')+def.singular;$('#fields').innerHTML=Object.entries(def.fields).map(([k,[label,kind]])=>{const value=row[k]??(kind==='date'?today():kind==='number'?(k==='interval'?30:0):'');let control;if(Array.isArray(kind)||kind==='asset'){const opts=kind==='asset'?data.assets.map(a=>[a.id,a.name]):kind.map(s=>[s,s]);control=`<select name="${k}" required>${kind==='asset'?'<option value="">請選擇設備</option>':''}${opts.map(([v,t])=>`<option value="${esc(v)}" ${value===v?'selected':''}>${esc(t)}</option>`).join('')}</select>`;}else if(kind==='textarea')control=`<textarea name="${k}" rows="3" maxlength="4000">${esc(value)}</textarea>`;else control=`<input name="${k}" type="${kind}" value="${esc(value)}" required ${kind==='number'?`min="${k==='interval'?1:0}" step="${k==='cost'?'0.01':1}"`:'maxlength="200"'}>`;return `<label>${label}${control}</label>`;}).join('');$('#editor').showModal();}
$('#form').addEventListener('submit',e=>{e.preventDefault();try{const {type,id}=editing,row=Object.fromEntries(new FormData(e.target));for(const [k,[,kind]] of Object.entries(defs[type].fields))if(kind==='number')row[k]=Number(row[k]);validate(type,row,data.assets);row.id=id||defs[type].prefix+'-'+crypto.randomUUID().slice(0,8);const next=structuredClone(data);if(id)next[type][next[type].findIndex(r=>r.id===id)]=row;else next[type].unshift(row);if(save(next,`${id?'更新':'新增'}${defs[type].singular}：${row.name}`)){$('#editor').close();render();toast('已儲存紀錄');}}catch(err){toast(err.message);}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-new],[data-edit],[data-complete],[data-convert]');if(!b)return;if(b.dataset.new)openEditor(b.dataset.new);else if(b.dataset.edit)openEditor(b.dataset.edit,b.dataset.id);else if(b.dataset.complete){const next=structuredClone(data),p=next.plans.find(p=>p.id===b.dataset.complete);const base=p.due>today()?p.due:today();p.due=nextDate(base,p.interval);next.inspections.unshift({id:'IN-'+crypto.randomUUID().slice(0,8),name:'完成保養：'+p.name,asset:p.asset,owner:p.owner,due:today(),status:'合格',note:'由保養計畫完成操作建立紀錄。'});if(save(next,'完成保養：'+p.name)){render();toast('已記錄完成，並更新下次保養日期');}}else{const i=data.inspections.find(r=>r.id===b.dataset.convert);if(data.orders.some(o=>o.inspection===i.id)){toast('此異常已建立工單');return;}const next=structuredClone(data);next.orders.unshift({id:'WO-'+crypto.randomUUID().slice(0,8),name:'巡檢異常：'+i.name,asset:i.asset,owner:i.owner,due:today(),status:'待處理',priority:'高',cost:0,note:i.note,inspection:i.id});if(save(next,'巡檢異常轉工單：'+i.name)){toast('已建立維修工單');location.hash='orders';}}});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.matches('tr[data-edit]'))openEditor(e.target.dataset.edit,e.target.dataset.id);});
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;const pos=e.target.selectionStart;render();$('#search').focus();$('#search').setSelectionRange(pos,pos);}});document.addEventListener('change',e=>{if(e.target.id==='filter'){filter=e.target.value;render();}});
function download(text,name,type){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('#backup').onclick=()=>download(JSON.stringify(data,null,2),'warebase-backup-'+today()+'.json','application/json');
$('#restore').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>10*1024*1024)throw Error('備份檔案不可超過 10 MB');const imported=validateBackup(JSON.parse(await file.text()));if(!confirm('還原將取代目前工作空間。建議先備份現有資料，確定還原？'))return;if(save(imported,'從備份還原工作空間')){render();toast('已還原備份');}}catch(err){toast('還原失敗：'+err.message);}finally{e.target.value='';}};
document.addEventListener('click',e=>{if(e.target.id==='csv'){const fields=['id',...Object.keys(defs[view].fields)];const csvCell=v=>'"'+String(v??'').replace(/^[=+@\-\t\r]/,"'$&").replace(/"/g,'""')+'"';download('\ufeff'+[fields.map(csvCell).join(','),...data[view].map(r=>fields.map(k=>csvCell(k==='asset'?assetName(r[k]):r[k])).join(','))].join('\r\n'),view+'-'+today()+'.csv','text/csv;charset=utf-8');toast('已匯出此模組全部紀錄');}});
$('#close').onclick=$('#cancel').onclick=()=>$('#editor').close();window.addEventListener('hashchange',()=>{query='';filter='';render();});window.addEventListener('storage',e=>{if(e.key===key&&e.newValue){try{data=validateBackup(JSON.parse(e.newValue));render();toast('已同步另一分頁的更新');}catch{toast('另一分頁的資料無效，請重新整理。');}}});render();
